package cli

import (
	"fmt"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func syncCmd() *cobra.Command {
	var verbose bool
	var push bool
	var cont bool
	var abort bool

	cmd := &cobra.Command{
		Use:   "sync <feature>",
		Short: "Rebase worktrees in dependency order",
		Args:  cobra.ExactArgs(1),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if len(args) == 0 {
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			}
			return nil, cobra.ShellCompDirectiveNoFileComp
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			internal.RequireTool("git")
			feature := args[0]
			featurePath := internal.FeaturePath(feature)

			if abort {
				return handleSyncAbort(feature, featurePath)
			}
			if cont {
				return handleSyncContinue(feature, featurePath, push)
			}
			if internal.HasSyncState(featurePath) {
				state, _ := internal.LoadSyncState(featurePath)
				return fmt.Errorf("previous sync incomplete (failed on: %s); use --continue or --abort", state.FailedBranch)
			}

			result := syncFeature(feature, verbose)
			if !result.Complete {
				return fmt.Errorf("sync incomplete")
			}
			fmt.Println("Sync complete.")
			if push {
				fmt.Println("\nPushing...")
				pushFeature(feature, false)
			}
			return nil
		},
	}

	cmd.Flags().BoolVarP(&verbose, "verbose", "v", false, "Show full git fetch output")
	cmd.Flags().BoolVar(&push, "push", false, "Push all branches after syncing")
	cmd.Flags().BoolVar(&cont, "continue", false, "Resume after conflict resolution")
	cmd.Flags().BoolVar(&abort, "abort", false, "Discard sync state and start fresh")

	return cmd
}

func handleSyncAbort(feature, featurePath string) error {
	state, err := internal.LoadSyncState(featurePath)
	if err != nil {
		fmt.Println("Nothing to abort — no sync in progress.")
		return nil
	}
	if state.FailedBranch != "" {
		path := internal.WorktreePath(feature, state.FailedBranch)
		if isRebaseInProgress(path) {
			_ = internal.RunSilentDir(path, "git", "rebase", "--abort")
		}
	}
	internal.DeleteSyncState(featurePath)
	fmt.Println("Sync state cleared.")
	return nil
}

func handleSyncContinue(feature, featurePath string, push bool) error {
	state, err := internal.LoadSyncState(featurePath)
	if err != nil {
		return fmt.Errorf("nothing to continue — no sync in progress")
	}
	failedPath := internal.WorktreePath(feature, state.FailedBranch)
	if state.FailedBranch != "" && isRebaseInProgress(failedPath) {
		return fmt.Errorf("rebase still in progress in %s; resolve conflicts, run git add . && git rebase --continue, then retry", state.FailedBranch)
	}

	stack, err := internal.LoadStack(featurePath)
	if err != nil {
		return fmt.Errorf("load stack: %w", err)
	}
	if state.FailedBranch != "" {
		failedEntry := internal.GetBranch(stack, state.FailedBranch)
		if failedEntry.Name == "" {
			return fmt.Errorf("failed branch %q no longer exists in stack", state.FailedBranch)
		}
		if !branchContainsConfiguredParent(feature, stack, failedEntry) {
			return fmt.Errorf("resolved branch %s still does not contain its configured parent %s", failedEntry.Name, failedEntry.Base)
		}
		fmt.Println(formatSyncStatus(state.FailedBranch, "active", "resolved"))
	}

	done := make(map[string]bool)
	for _, name := range state.Completed {
		done[name] = true
	}
	if state.FailedBranch != "" {
		done[state.FailedBranch] = true
	}
	sorted, err := internal.TopoSort(stack)
	if err != nil {
		return err
	}
	fmt.Printf("Resuming sync with %d pending branch(es)\n", len(state.Pending))
	result := syncWithStackFiltered(feature, featurePath, stack, sorted, done)
	if !result.Complete {
		return fmt.Errorf("sync incomplete")
	}
	fmt.Println("Sync complete.")
	if push {
		fmt.Println("\nPushing...")
		pushFeature(feature, false)
	}
	return nil
}

func branchContainsConfiguredParent(feature string, stack internal.Stack, child internal.StackEntry) bool {
	parent := internal.GetBranch(stack, child.Base)
	if parent.Name == "" || !sameStackRepo(parent.Repo, child.Repo) {
		return true
	}
	path := internal.WorktreePath(feature, child.Name)
	return internal.RunSilentDir(path, "git", "merge-base", "--is-ancestor", parent.GitBranch(), child.GitBranch()) == nil
}

func isRebaseInProgress(worktreePath string) bool {
	// Check for .git/rebase-merge or .git/rebase-apply
	gitDir := internal.RunSilent("git", "-C", worktreePath, "rev-parse", "--git-dir")
	if gitDir != nil {
		return false
	}
	// Simpler: check if git status shows rebase
	err := internal.RunSilent("git", "-C", worktreePath, "rebase", "--show-current-patch")
	return err == nil
}

func syncFeature(feature string, verbose bool) syncResult {
	featurePath := internal.FeaturePath(feature)

	stack, err := internal.LoadStack(featurePath)
	if err != nil {
		fetchQuiet("", "", verbose)
		syncFallback(featurePath)
		return syncResult{Complete: true}
	}

	repos := internal.UniqueRepos(stack, featurePath)
	for repo, wtPath := range repos {
		fetchQuiet(repo, wtPath, verbose)
	}

	sorted, err := internal.TopoSort(stack)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return syncResult{}
	}
	return syncWithStack(feature, featurePath, stack, sorted)
}

func fetchQuiet(repo, wtPath string, verbose bool) {
	label := "default repo"
	if repo != "" {
		label = repo
	}

	if verbose {
		fmt.Printf("Fetching %s...\n", label)
		if wtPath != "" {
			_ = internal.RunDir(wtPath, "git", "fetch")
		} else if repo != "" {
			_ = internal.RunDir(repo, "git", "fetch")
		} else {
			_ = internal.Run("git", "fetch")
		}
	} else {
		fmt.Printf("Fetching %s... ", label)
		var err error
		if wtPath != "" {
			err = internal.RunSilentDir(wtPath, "git", "fetch")
		} else if repo != "" {
			err = internal.RunSilentDir(repo, "git", "fetch")
		} else {
			err = internal.RunSilent("git", "fetch")
		}
		if err != nil {
			fmt.Println("failed")
		} else {
			fmt.Println("done")
		}
	}
}

package cli

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
)

func TestSyncContinueResumesDescendants(t *testing.T) {
	repo := setupGitRepo(t, "master")
	withWorkspaceEnv(t, repo)
	createLinearStack(t, repo, "feature")

	featurePath := internal.FeaturePath("feature")
	parentPath := internal.WorktreePath("feature", "parent")
	childPath := internal.WorktreePath("feature", "child")
	parentOld := gitOutput(t, parentPath, "rev-parse", "HEAD")
	writeAndCommit(t, parentPath, "parent.txt", "parent-v2\n", "parent v2")
	parentNew := gitOutput(t, parentPath, "rev-parse", "HEAD")
	if parentOld == parentNew {
		t.Fatal("parent did not advance")
	}

	state := internal.NewSyncState()
	state.FailedBranch = "parent"
	state.Completed = []string{"root"}
	state.Pending = []string{"child"}
	if err := internal.SaveSyncState(featurePath, state); err != nil {
		t.Fatal(err)
	}

	if err := handleSyncContinue("feature", featurePath, false); err != nil {
		t.Fatalf("handleSyncContinue: %v", err)
	}
	if internal.HasSyncState(featurePath) {
		t.Fatal("sync state was not cleared after complete continuation")
	}
	if internal.RunSilentDir(childPath, "git", "merge-base", "--is-ancestor", parentNew, "child") != nil {
		t.Fatal("child does not contain updated parent")
	}
}

func TestSyncContinueRetainsStateOnLaterFailure(t *testing.T) {
	repo := setupGitRepo(t, "master")
	withWorkspaceEnv(t, repo)
	createLinearStack(t, repo, "feature")

	featurePath := internal.FeaturePath("feature")
	parentPath := internal.WorktreePath("feature", "parent")
	childPath := internal.WorktreePath("feature", "child")
	writeAndCommit(t, parentPath, "conflict.txt", "from-parent\n", "parent change")
	writeAndCommit(t, childPath, "conflict.txt", "from-child\n", "child change")

	state := internal.NewSyncState()
	state.FailedBranch = "parent"
	state.Completed = []string{"root"}
	state.Pending = []string{"child"}
	if err := internal.SaveSyncState(featurePath, state); err != nil {
		t.Fatal(err)
	}

	if err := handleSyncContinue("feature", featurePath, false); err == nil {
		t.Fatal("expected child conflict")
	}
	persisted, err := internal.LoadSyncState(featurePath)
	if err != nil {
		t.Fatalf("sync state not retained: %v", err)
	}
	if persisted.FailedBranch != "child" {
		t.Fatalf("failed branch = %q, want child", persisted.FailedBranch)
	}
}

func createLinearStack(t *testing.T, repo, feature string) {
	t.Helper()
	if err := createWorktree(feature, "root", "master", repo, false); err != nil {
		t.Fatal(err)
	}
	rootPath := internal.WorktreePath(feature, "root")
	writeAndCommit(t, rootPath, "root.txt", "root\n", "root")

	if err := createWorktree(feature, "parent", "root", repo, false); err != nil {
		t.Fatal(err)
	}
	parentPath := internal.WorktreePath(feature, "parent")
	writeAndCommit(t, parentPath, "parent-only.txt", "parent\n", "parent")

	if err := createWorktree(feature, "child", "parent", repo, false); err != nil {
		t.Fatal(err)
	}
	childPath := internal.WorktreePath(feature, "child")
	writeAndCommit(t, childPath, "child.txt", "child\n", "child")

	// Ensure injected symlinks do not affect test cleanliness.
	for _, path := range []string{rootPath, parentPath, childPath} {
		_ = os.Remove(filepath.Join(path, "CLAUDE.local.md"))
	}
}

package cli

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
)

type syncResult struct {
	Complete bool
	Failed   string
}

func syncWithStack(feature, featurePath string, stack internal.Stack, sorted []internal.StackEntry) syncResult {
	return syncWithStackFiltered(feature, featurePath, stack, sorted, nil)
}

func syncWithStackFiltered(feature, featurePath string, stack internal.Stack, sorted []internal.StackEntry, alreadyDone map[string]bool) syncResult {
	updatedByRef := make(map[string]bool)
	completed := completedNames(alreadyDone)
	if alreadyDone == nil {
		alreadyDone = make(map[string]bool)
	}

	for _, entry := range sorted {
		if alreadyDone[entry.Name] {
			continue
		}
		path := internal.WorktreePath(feature, entry.Name)
		if _, err := os.Stat(path); os.IsNotExist(err) {
			continue
		}

		if issue := internal.CheckWorktreeBranch(path, entry.GitBranch()); issue != nil {
			fmt.Println(formatSyncStatus(entry.Name, "active", "wrong-branch"))
			fmt.Printf("    %s\n    %s\n", issue.Problem, issue.Hint)
			return saveIncompleteSync(featurePath, sorted, completed, entry.Name)
		}

		base := resolveEntryBase(stack, entry)
		gitContext := path
		if entry.Repo != "" {
			gitContext = entry.Repo
		}
		currentBaseSHA := internal.GetBranchSHA(gitContext, base)
		rebaseArgs := []string{"rebase", "--update-refs", base}
		if entry.LastBaseSHA != "" && currentBaseSHA != "" && entry.LastBaseSHA != currentBaseSHA {
			rebaseArgs = []string{"rebase", "--update-refs", "--onto", base, entry.LastBaseSHA}
		}

		if err := internal.RunDirClean(path, "git", rebaseArgs...); err != nil {
			fmt.Println(formatSyncStatus(entry.Name, "active", "conflict"))
			fmt.Printf("    Resolve conflicts in: %s\n", path)
			fmt.Println("    Then run: git add . && git rebase --continue")
			fmt.Printf("    Resume with: tws sync %s --continue\n", feature)
			return saveIncompleteSync(featurePath, sorted, completed, entry.Name)
		}
		if !runValidation(path, entry.Name) {
			return saveIncompleteSync(featurePath, sorted, completed, entry.Name)
		}

		fmt.Println(formatSyncStatus(entry.Name, "active", "synced"))
		markUpdatedAncestors(stack, entry.Name, featurePath, updatedByRef)
		completed = append(completed, entry.Name)
		alreadyDone[entry.Name] = true
		if currentBaseSHA != "" {
			internal.UpdateBaseSHA(&stack, entry.Name, currentBaseSHA)
			_ = internal.SaveStack(featurePath, stack)
		}
	}

	for _, entry := range sorted {
		if alreadyDone[entry.Name] {
			continue
		}
		path := internal.WorktreePath(feature, entry.Name)
		if _, err := os.Stat(path); err == nil {
			continue
		}
		if internal.IsPrunableWorktree(entry.GitBranch()) {
			fmt.Printf("  [?] %s (missing — run: tws archive %s %s or tws new %s %s)\n", entry.Name, feature, entry.Name, feature, entry.Name)
			return saveIncompleteSync(featurePath, sorted, completed, entry.Name)
		}
		if updatedByRef[entry.Name] {
			fmt.Println(formatSyncStatus(entry.Name, "archived", "synced"))
			completed = append(completed, entry.Name)
			alreadyDone[entry.Name] = true
			continue
		}

		base := resolveEntryBase(stack, entry)
		rebaseDir := entry.Repo
		var err error
		if rebaseDir != "" {
			err = internal.RunSilentDir(rebaseDir, "git", "rebase", base, entry.GitBranch())
		} else {
			err = internal.RunSilent("git", "rebase", base, entry.GitBranch())
		}
		if err != nil {
			if rebaseDir != "" {
				_ = internal.RunSilentDir(rebaseDir, "git", "rebase", "--abort")
			} else {
				_ = internal.RunSilent("git", "rebase", "--abort")
			}
			fmt.Println(formatSyncStatus(entry.Name, "archived", "conflict"))
			fmt.Printf("    Restore with: tws new %s %s\n", feature, entry.Name)
			return saveIncompleteSync(featurePath, sorted, completed, entry.Name)
		}
		fmt.Println(formatSyncStatus(entry.Name, "archived", "synced"))
		completed = append(completed, entry.Name)
		alreadyDone[entry.Name] = true
	}

	if stale := staleStackEdges(feature, stack); len(stale) > 0 {
		fmt.Println("Sync incomplete; stale stack edges remain:")
		for _, edge := range stale {
			fmt.Printf("  [!] %s\n", edge)
		}
		return saveIncompleteSync(featurePath, sorted, completed, "")
	}
	internal.DeleteSyncState(featurePath)
	return syncResult{Complete: true}
}

func saveIncompleteSync(featurePath string, sorted []internal.StackEntry, completed []string, failed string) syncResult {
	completedSet := make(map[string]bool, len(completed))
	for _, name := range completed {
		completedSet[name] = true
	}
	pending := make([]string, 0)
	for _, entry := range sorted {
		if entry.Name != failed && !completedSet[entry.Name] {
			pending = append(pending, entry.Name)
		}
	}
	state := internal.NewSyncState()
	state.FailedBranch = failed
	state.Pending = pending
	state.Completed = append([]string(nil), completed...)
	_ = internal.SaveSyncState(featurePath, state)
	return syncResult{Failed: failed}
}

func completedNames(done map[string]bool) []string {
	var names []string
	for name, ok := range done {
		if ok {
			names = append(names, name)
		}
	}
	return names
}

func staleStackEdges(feature string, stack internal.Stack) []string {
	var stale []string
	for _, child := range stack.Branches {
		parent := internal.GetBranch(stack, child.Base)
		if parent.Name == "" || !sameStackRepo(parent.Repo, child.Repo) {
			continue
		}
		childPath := internal.WorktreePath(feature, child.Name)
		if _, err := os.Stat(childPath); err != nil {
			continue
		}
		if internal.RunSilentDir(childPath, "git", "merge-base", "--is-ancestor", parent.GitBranch(), child.GitBranch()) != nil {
			stale = append(stale, fmt.Sprintf("%s does not contain parent %s", child.Name, parent.Name))
		}
	}
	return stale
}

func resolveEntryBase(stack internal.Stack, entry internal.StackEntry) string {
	if parent := internal.GetBranch(stack, entry.Base); parent.Name != "" && sameStackRepo(parent.Repo, entry.Repo) {
		return parent.GitBranch()
	}
	return resolveBase(entry.Base)
}

func resolveBase(base string) string {
	defaultBranch := internal.DefaultBranch()
	if base == defaultBranch {
		return "origin/" + defaultBranch
	}
	return base
}

func markUpdatedAncestors(stack internal.Stack, branch string, featurePath string, updated map[string]bool) {
	entryMap := make(map[string]internal.StackEntry)
	for _, e := range stack.Branches {
		entryMap[e.Name] = e
	}
	current := branch
	for {
		entry, ok := entryMap[current]
		if !ok {
			break
		}
		parent, ok := entryMap[entry.Base]
		if !ok {
			break
		}
		parentPath := filepath.Join(featurePath, "worktrees", parent.Name)
		if _, err := os.Stat(parentPath); os.IsNotExist(err) {
			updated[parent.Name] = true
		}
		current = parent.Name
	}
}

func formatSyncStatus(name, mode, status string) string {
	symbols := map[string]string{"synced": "+", "failed": "x", "skipped": "-", "conflict": "!", "resolved": "~", "wrong-branch": "?", "validation-failed": "x"}
	sym := symbols[status]
	if sym == "" {
		sym = "?"
	}
	return fmt.Sprintf("  [%s] %s (%s)", sym, name, mode)
}

func syncFallback(featurePath string) {
	entries, _ := os.ReadDir(filepath.Join(featurePath, "worktrees"))
	for _, e := range entries {
		if e.IsDir() {
			path := filepath.Join(featurePath, "worktrees", e.Name())
			fmt.Printf("Syncing worktree: %s\n", path)
			internal.Must(internal.RunDirClean(path, "git", "rebase", "--update-refs", "origin/main"))
		}
	}
}

func runValidation(worktreePath, branchName string) bool {
	cfg := internal.LoadConfig()
	if cfg.TestCommand == "" {
		return true
	}
	fmt.Printf("    validating %s: %s... ", branchName, cfg.TestCommand)
	parts := strings.Fields(cfg.TestCommand)
	if err := internal.RunSilentDir(worktreePath, parts[0], parts[1:]...); err != nil {
		fmt.Println("FAILED")
		fmt.Println(formatSyncStatus(branchName, "active", "validation-failed"))
		return false
	}
	fmt.Println("ok")
	return true
}
